standard_library.install_aliases()
logger = BackgroundLogger.Instance()


class AnalysePcap(object):
    """Analyse pcap"""
    def __init__(self):
        self.tshark_loc = "/bin/tshark"
        self.path = BuiltIn().get_variable_value("${EXEC_DIR}")
        # self.config = get_variables()
        self.config = ConfigHandler.get_config()

    def _fetch_filter(self, analysis):
        """

        Args:
            analysis:

        Returns:

        """
        return get_config_variable(["traffic_analysis", analysis, "filter"])

    def _load_pcap(self, pcap_input):
        logger.debug("_load_pcap")
        shared_path = self.path + "\\" + pcap_input
        if os.path.isfile(shared_path) and os.access(shared_path, os.R_OK):
            logger.debug("File exists and is readable")
            return 1
        else:
            logger.error("File is missing or not readable")
            return 0

    def _get_frame_list(self, filter_code=None, needed_fields=None,
                        decode_query=None, exp_time_interval=None,
                        exp_time_interval_tolerance=0):
        logger.debug("Packet capture file " + self.packet_capture_file)

        if needed_fields:
            fields = "  -e frame.number -e " + needed_fields
        elif exp_time_interval:
            fields = None
        else:
            fields = " -e frame.number"
        query_string = 'tshark -o esp.enable_encryption_decode:TRUE -r ' + self.packet_capture_file
        if decode_query:
            query_string = query_string + ' -d ' + decode_query
        if filter_code and fields:
            query_string = query_string + ' -Y "' + filter_code +\
                           '" -T fields' + fields
        # -Y for 2.0.2 version of wireshark, -R for older version of wireshark
        elif exp_time_interval:
            exp_time_interval = round((float(exp_time_interval) +
                                       (float(exp_time_interval_tolerance) /
                                        float(100) * float(exp_time_interval
                                                           ))), 2)
            query_string =\
                query_string + ' -Y "' + filter_code +\
                '" -w - | tshark -r - -Y "frame.time_relative <= ' + str(
                    exp_time_interval) + ' "'
        else:
            query_string = query_string + ' -T fields ' + fields
        output = self._run_tshark_query(query_string)
        frame_numbers_list = output.splitlines()
        logger.info("frames obtained from tshark Query" +
                    str(frame_numbers_list))
        return 0, len(frame_numbers_list) - 1, frame_numbers_list

    def _verify_count(self, count_query, count, packet_tolerance, option_list,
                      decode_query, exp_time_interval,
                      exp_time_interval_tolerance):
        lower_bound, upper_bound = _convert_range(count)
        if not option_list:
            temp1, count_packet, temp_list = self._get_frame_list(
                filter_code=count_query, decode_query=decode_query,
                exp_time_interval=exp_time_interval,
                exp_time_interval_tolerance=exp_time_interval_tolerance)
            count_packet += 1
            logger.info("Required count :" + count + " Actual Count :" +
                        str(count_packet))
            logger.info("Packet Tolerance :{}".format(packet_tolerance))
            lower = lower_bound - packet_tolerance * lower_bound / 100
            upper = upper_bound + packet_tolerance * upper_bound / 100
            if not (lower <= count_packet <= upper):
                _exit_with_error("Packet Count doesnt Match for query " +
                                 count_query)
            else:
                logger.info("Packet count matched  for query " + count_query)
                return count_packet
        else:
            logger.info("Analysing the option list " + option_list)
            failed_query = ""
            for option in option_list.split(','):
                new_query = count_query.replace("<XX>", option)
                logger.info("Modified query as per option list " + new_query)
                temp1, count_packet, temp_list = self._get_frame_list(
                    new_query, decode_query=decode_query)
                logger.info("Required count :" + count + " Actual Count :" +
                            str(count_packet))
                if not ((count_packet >= lower_bound) and (count_packet <=
                                                           upper_bound)):
                    failed_query = failed_query + " " + new_query
                    logger.warn("Packet count doesnt match for query" +
                                new_query)
                else:
                    logger.info("Packet count matched  for query " + new_query)
            if failed_query:
                _exit_with_error("Packet count failed for queries " +
                                 failed_query)

    @check_rat
    def analyse_pcap(self, **kwargs):
        """
        This function analyses a given wireshark capture based on the given
        analysis.
        The function will analyse pass or fail based on the analysis. It can
        also return values from the capture file based on the
        Args:
            pcap_filename: (string) Name of the pcap file.
            analysis: (string) Analysis name. This will be read from the
            filters file.
            filter_file_name: (string) Name of the file having the filters for
            analysis

        Returns:

        """
        # self.filter_file_content = self._get_json_file_content(
        #     filter_file_name)
        pcap_filename = kwargs.pop('pcap_filename')
        analysis = kwargs.pop('analysis')
        filter_file_name = kwargs.pop('filter_file_name', "traffic_filters.json")
        admin_alias = kwargs.pop('admin_alias', None)
        variables = kwargs.pop('variables', '')
        self.filter_file_content = resource_file.load_json_file(
            filter_file_name)
        analysis_dict = self.filter_file_content['traffic_analysis'].get(
            analysis)
        if analysis_dict is None:
            raise Exception("Analysis {0} not present in the given traffic"
                            " filters file".format(analysis))
        else:
            if analysis_dict["eval"] == "getValue":
                return self._extract_packet_details_from_pcap_file(
                    pcap_filename, analysis)
            elif analysis_dict["eval"] == "count":
                return self.analyse_packet_capture_count(
                    pcap_filename, self.filter_file_content['traffic_analysis']
                    [analysis], admin_alias=admin_alias, variables=variables)

    def _extract_packet_details_from_pcap_file(self, captured_file_name,
                                               analysis):
        tshark_cmd = self._get_tshark_cmd(captured_file_name, analysis)
        tshark_output = self.execute_tshark_cmd(tshark_cmd)
        return self.extract_layer_value_from_tshark_json_output(tshark_output)

    def _get_tshark_cmd(self, captured_file_name, analysis):
        tshark_cmd = self._get_tshark_basic_cmd(captured_file_name)
        tshark_cmd = self._set_tshark_options_for_tshark_cmd(
            analysis, tshark_cmd, "decode_as", "-d")
        tshark_cmd = self._set_tshark_options_for_tshark_cmd(
            analysis, tshark_cmd, "filter", "-Y")
        tshark_cmd = self._set_tshark_display_options_for_tshark_cmd(
            analysis, tshark_cmd, "display_fields", "-e")
        logger.info("tshark command to be executed :: {0}".format(tshark_cmd))
        return tshark_cmd

    def _get_tshark_basic_cmd(self, captured_file_name):
        self._set_pcap_file(captured_file_name)
        return "tshark -T  json -r {0}".format(self.packet_capture_file)

    def _set_tshark_display_options_for_tshark_cmd(
            self, analysis, tshark_cmd, option_type, option_character):
        if get_config_variable(["traffic_analysis", analysis, option_type],
                               self.filter_file_content):
            for tshark_option in get_config_variable(
                    ["traffic_analysis", analysis, option_type],
                    self.filter_file_content).split(","):
                tshark_cmd += " {} {}".format(option_character,
                                              tshark_option.strip())
        return tshark_cmd

    def _set_tshark_options_for_tshark_cmd(self, analysis, tshark_cmd,
                                           option_type, option_character):
        # if _get_config_variable(["traffic_analysis",analysis,option_type]):
        logger.info("{} : Analysis ".format(analysis))
        option_type = get_config_variable(["traffic_analysis", analysis,
                                           option_type],
                                          self.filter_file_content)
        if option_type:
            tshark_cmd += " {} '{}'".format(option_character,
                                            option_type.strip())
        return tshark_cmd

    def execute_tshark_cmd(self, tshark_cmd):
        """Execute tshark command"""
        subprocess_output = subprocess.Popen(
            tshark_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            shell=True)
        tshark_output, tshark_err = subprocess_output.communicate()
        tshark_output = decode_str(tshark_output)
        tshark_err = decode_str(tshark_err)
        logger.info("tshark output :: \n{}".format(str(tshark_output)))
        user_err_msg = "tshark error\nCommand error output :: {}".format(
            str(tshark_err))
        if tshark_err:
            if tshark_output:
                logger.warn(user_err_msg)
            else:
                raise Exception(user_err_msg)
        return tshark_output

    def extract_layer_value_from_tshark_json_output(self, tshark_output):
        """Extract layer value from tshark json output"""
        logger.debug("extracting layer value from tshark json output")
        if tshark_output == "":
            raise Exception("tshark command output is empty. Unable to extract"
                            " packet details.")
        packet_details = []
        for packet in json.loads(tshark_output):
            packet_details.append(packet.get("_source").get("layers"))
        else:
            return packet_details

    def analyse_packet_capture_count(self, captured_file_name, analysis,
                                     option_list=None, decode_query=None,
                                     admin_alias=None, variables=''):
        """Analyse packet capture count"""
        logger.debug("Inside analysis packet count")
        exp_time_interval = None
        exp_time_interval_tolerance = 0
        if "exp_time_interval" in list(analysis.keys()):
            exp_time_interval = int(analysis["exp_time_interval"])
        if "exp_time_interval_tolerance" in list(analysis.keys()):
            exp_time_interval_tolerance = int(
                analysis["exp_time_interval_tolerance"])
        self._set_pcap_file(captured_file_name)
        capture_filter = analysis["filter"]
        # query = _format_capture_filter(capture_filter, admin_alias)
        query = replace_with_builtin_and_admin_values.replace(
            capture_filter, admin_alias=admin_alias, variables=variables)
        logger.info("query: " + query)
        count = analysis["expected_result"]
        packet_tolerance = analysis["tolerance"]
        if "decode_as" in list(analysis.keys()):
            decode_query = analysis["decode_as"]
        return self._verify_count(query, count, packet_tolerance, option_list,
                                  decode_query, exp_time_interval,
                                  exp_time_interval_tolerance)

    def _set_pcap_file(self, pcap_file_name):
        self.packet_capture_file = pcap_file_name
        if os.path.isfile(self.packet_capture_file):
            logger.info("PCAP File : " + self.packet_capture_file)
        else:
            BuiltIn().fail("Pcap file : " + self.packet_capture_file +
                           " not found")

    def _run_tshark_query(self, query_string):
        logger.info("Query String is " + str(query_string))
        out = subprocess.Popen(query_string, stdout=subprocess.PIPE,
                               stderr=subprocess.PIPE, shell=True)
        output, err = out.communicate()
        return output

    @check_rat
    def get_throughput(self, **kwargs):
        """Get throughput"""
        filename = kwargs.pop('filename')
        pcap_filter = kwargs.pop('pcap_filter', '')
        data_unit = kwargs.pop('data_unit', 'bytes')
        pcap_filter = pcap_filter if pcap_filter == '' else ',{}'.format(
            pcap_filter)

        logger.debug("executing tshark command...")
        cmd = 'tshark -r {pcap} -qz io,stat,0,FRAMES,BYTES{pcap_filter}'\
            .format(pcap=filename, pcap_filter=pcap_filter)
        logger.debug(cmd)
        output = subprocess.check_output(cmd, shell=True)
        logger.debug(output)
        output_lines = output.splitlines()
        duration =\
            re.search(r'Duration:\s+(.+?)\s+secs', output_lines[4]).group(1)
        summary_line = self._replace_using_regex(r"\s+", '', output_lines[-2])
        summary_fields = summary_line.split('|')
        data_fields = self._get_data_fields_from_summary(data_unit,
                                                         summary_fields)
        throughput_dict = {}
        pcap_filters = pcap_filter.split(',')
        logger.info('Total Duration: {} secs'.format(duration))
        for index in range(0, len(data_fields), 1):
            data_field = data_fields[index]
            throughput = float(data_field) / float(duration)
            throughput = int(round(throughput))
            if index == 0:
                throughput_dict['Total'] = throughput
                logger.info('Total Throughput: {} {}/Sec, Data exchanged:'
                            ' {} {}'.format(throughput, data_unit, data_field,
                                            data_unit))
            else:
                throughput_dict[pcap_filters[index]] = throughput
                logger.info('{} Throughput: {} {}/Sec, Data exchanged: {}'
                            ' {}'.format(pcap_filters[index], throughput,
                                         data_unit, data_field, data_unit))
        return throughput_dict

    def _get_data_fields_from_summary(self, data_unit, summary_fields):
        logger.debug("getting data fields from summary....")
        # When filters are applied, there will be more than one data field.
        # No filters supported as of now
        data_fields = []
        start_index = 3 if data_unit.lower() == 'bytes' else 2
        summary_fields.pop(-1)  # Remove empty item at the end
        for index in range(start_index, len(summary_fields), 2):
            data_fields.append(summary_fields[index])
        return data_fields

    def _replace_using_regex(self, regex, new, string_to_replace):
        logger.debug("replacing strings using regex....")
        regex_compiled = re.compile(regex)
        return regex_compiled.sub(new, string_to_replace)


def _convert_range(range_value):
    lower = range_value.split('-')
    if len(lower) == 2:
        lower_bound = (re.search("[0-9]+", lower[0], re.U | re.I)).group()
        if lower[1] == '*':
            upper_bound = sys.maxsize
        else:
            upper_bound = (re.search("[0-9]+", lower[1], re.U | re.I)).group()
    elif len(lower) == 1:
        upper_bound = lower_bound = \
            (re.search("[0-9]+", lower[0], re.U | re.I)).group()
    else:
        logger.error("Please provide a valid range")
        return 0
    return int(lower_bound), int(upper_bound)


def _get_repeat_count(list_of_queries):
    repeat_value = 0
    for query in list_of_queries:
        if "repeat" in list(query.keys()):
            repeat_value = query["repeat"]
            logger.info("Repeat value is " + repeat_value + " for query list "
                        + str(list_of_queries))
            break
    return repeat_value


def _exit_with_error(message):
    BuiltIn().fail(message)
